//! Actual trusted replacement synchronizes parsed native defaults and Reset and nearby App state.
use super::*;
struct Fixture(std::path::PathBuf);
impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.attr(n,"id")==Some(id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
#[test]
fn textarea_inner_html_actual_app_trusted_parsed_default_and_native_reset_keeps_paint_editor_and_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-textarea-inner-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><html><head><style>body{margin:0;background:white}#paint{position:absolute;left:20px;top:20px;width:120px;height:32px;background:#114455}#paint.ready{background:#228844}#go{position:absolute;left:220px;top:20px;width:160px;height:32px}#mount{position:absolute;left:20px;top:180px;width:560px}#neighbor{position:absolute;left:220px;top:100px;width:180px;height:30px}#stable{position:absolute;left:420px;top:100px}</style></head><body><div id=paint>Indicator</div><form id=form><textarea id=context style="position:absolute;left:20px;top:230px;width:160px;height:40px">Held</textarea><button id=reset type=reset style="position:absolute;left:220px;top:230px;width:160px;height:32px">Reset</button></form><div id=mount></div><input id=neighbor value=neighbor><a id=stable href=#destination>Go</a><button id=go type=button>Insert literal source</button><div id=destination></div><script>
var context=document.getElementById('context'),watch=new MutationObserver(function(){});watch.observe(context,{childList:true,characterData:true,subtree:true});document.getElementById('go').onclick=function(e){if(!e.isTrusted)throw 'actual trusted pointer';var old=context.firstChild,expected='New\n\r&\ud835\udd04<img id=fake src=missing>&lt;';context.innerHTML='New\r\n&#13;&amp;&Afr;&lt;img id=fake src=missing&gt;&amp;lt;';var text=context.firstChild,records=watch.takeRecords();if(text===old||text.data!==expected||context.defaultValue!==expected||context.value!=='kept edit'||text.ownerDocument!==document||text.parentNode!==context||!text.isConnected||old.parentNode!==null||old.data!=='Held'||records.length!==1||records[0].target!==context||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==text||document.getElementById('fake')!==null||document.getElementById('neighbor').value!=='edited neighbor')throw 'actual parsed native textarea default';document.getElementById('paint').className='ready';document.title='Native textarea parsed default';};
</script></body></html>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let before=app.draw();assert_eq!(before.pixels[(app.content_top()+40)as usize*before.width+110],0x114455);
 let go=node(&app,"go");let neighbor=node(&app,"neighbor");let stable=node(&app,"stable");app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let context=node(&app,"context");app.forms.script_set_value(context,"kept edit").unwrap();{let e=&mut app.forms.controls.get_mut(&context).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}let raw=app.raw.clone();let location=app.location.clone();let epoch=app.script_epoch;let scroll=app.scroll;
 let rect=app.page.controls.iter().find(|r|r.node==go).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);
 assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());assert_eq!(app.document.title,"Native textarea parsed default");
 let [text]=app.document.nodes[context].children.as_slice()else{panic!("one actual native Text")};let text_index=*text;let crate::html::NodeKind::Text(text)=&app.document.nodes[text_index].kind else{panic!("native Text")};assert_eq!(text.as_str(),"New\n\r&\u{1d504}<img id=fake src=missing>&lt;");assert!(!app.document.nodes.iter().enumerate().any(|(n,_)|app.document.attr(n,"id")==Some("fake")));let c=&app.forms.controls[&context];assert_eq!((c.value.text(),c.value.cursor,c.value.anchor,c.value.offset),("kept edit".into(),5,2,1));assert!(c.dirty_value);
 let reset=node(&app,"reset");let rect=app.page.controls.iter().find(|r|r.node==reset).unwrap();let(x,y)=(rect.x+rect.width/2,app.content_top()+rect.y+rect.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);let c=&app.forms.controls[&context];assert_eq!(c.value.text(),"New\n\n&\u{1d504}<img id=fake src=missing>&lt;");assert!(!c.dirty_value);assert_eq!(app.document.nodes[context].children,vec![text_index]);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0);
 let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+40)as usize*painted.width+110],0x228844);let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!(app.raw,raw);assert_eq!(app.location,location);assert_eq!(app.script_epoch,epoch);assert_eq!(app.scroll,scroll);
}
